@app.get('/books/{book_id}')
def get_book(book_id: int):
    book = db.get(book_id)
    if not book:
        raise HTTPException(404, 'not found')
    return {'id': book.id, 'title': book.title, 'year': book.year}

@app.post('/books', status_code=201)
def create_book(body: BookIn):  # title: str, year: int | None
    return db.create(body)
